IF DB_ID('TradingDB') IS NULL CREATE DATABASE TradingDB;
GO
USE TradingDB;
GO
CREATE TABLE Users(UserId INT IDENTITY PRIMARY KEY, Username NVARCHAR(50) NOT NULL UNIQUE, PasswordHash NVARCHAR(100) NOT NULL, Salt NVARCHAR(50) NOT NULL, Role NVARCHAR(10) NOT NULL CHECK(Role IN('Admin','User')), IsActive BIT NOT NULL DEFAULT 1);
CREATE TABLE Units(UnitId INT IDENTITY PRIMARY KEY, UnitName NVARCHAR(200) NOT NULL UNIQUE);
CREATE TABLE Materials(MaterialId INT IDENTITY PRIMARY KEY, Name NVARCHAR(200) NOT NULL UNIQUE, UnitId INT NOT NULL REFERENCES Units(UnitId),
  PurchaseRate DECIMAL(18,2) NOT NULL DEFAULT 0, SaleRate DECIMAL(18,2) NOT NULL DEFAULT 0, MinStock DECIMAL(18,3) NOT NULL DEFAULT 0,
  Stock DECIMAL(18,3) NOT NULL DEFAULT 0 CHECK(Stock>=0));
CREATE TABLE Suppliers(SupplierId INT IDENTITY PRIMARY KEY, Name NVARCHAR(200) NOT NULL UNIQUE, Phone NVARCHAR(200) NOT NULL DEFAULT '', Address NVARCHAR(200) NOT NULL DEFAULT '');
CREATE TABLE Customers(CustomerId INT IDENTITY PRIMARY KEY, Name NVARCHAR(200) NOT NULL UNIQUE, Phone NVARCHAR(200) NOT NULL DEFAULT '', Address NVARCHAR(200) NOT NULL DEFAULT '');
CREATE TABLE Purchases(PurchaseId INT IDENTITY PRIMARY KEY, PurchaseDate DATE NOT NULL, SupplierId INT NOT NULL REFERENCES Suppliers(SupplierId),
  MaterialId INT NOT NULL REFERENCES Materials(MaterialId), Qty DECIMAL(18,3) NOT NULL CHECK(Qty>0), Rate DECIMAL(18,2) NOT NULL, Amount DECIMAL(18,2) NOT NULL,
  Remarks NVARCHAR(200) NOT NULL DEFAULT '', CreatedBy NVARCHAR(50) NOT NULL, CreatedOn DATETIME2 NOT NULL DEFAULT SYSDATETIME());
CREATE TABLE Sales(SaleId INT IDENTITY PRIMARY KEY, InvoiceNo AS ('INV-'+RIGHT('000000'+CAST(SaleId AS VARCHAR(10)),6)) PERSISTED, SaleDate DATE NOT NULL,
  CustomerId INT NOT NULL REFERENCES Customers(CustomerId), MaterialId INT NOT NULL REFERENCES Materials(MaterialId),
  Qty DECIMAL(18,3) NOT NULL CHECK(Qty>0), Rate DECIMAL(18,2) NOT NULL, Amount DECIMAL(18,2) NOT NULL, Delivery NVARCHAR(200) NOT NULL DEFAULT '',
  CreatedBy NVARCHAR(50) NOT NULL, CreatedOn DATETIME2 NOT NULL DEFAULT SYSDATETIME());
CREATE TABLE Receipts(ReceiptId INT IDENTITY PRIMARY KEY, PayDate DATE NOT NULL, CustomerId INT NOT NULL REFERENCES Customers(CustomerId),
  Amount DECIMAL(18,2) NOT NULL CHECK(Amount>0), Mode NVARCHAR(20) NOT NULL, Remarks NVARCHAR(200) NOT NULL DEFAULT '', CreatedBy NVARCHAR(50) NOT NULL);
CREATE TABLE Payments(PaymentId INT IDENTITY PRIMARY KEY, PayDate DATE NOT NULL, SupplierId INT NOT NULL REFERENCES Suppliers(SupplierId),
  Amount DECIMAL(18,2) NOT NULL CHECK(Amount>0), Mode NVARCHAR(20) NOT NULL, Remarks NVARCHAR(200) NOT NULL DEFAULT '', CreatedBy NVARCHAR(50) NOT NULL);
CREATE INDEX IX_Sales_Date ON Sales(SaleDate); CREATE INDEX IX_Purch_Date ON Purchases(PurchaseDate);
INSERT Units(UnitName) VALUES('Kg'),('Ton'),('Nos'),('Litre'),('Bag');
